use crate::aap::caps::inference_llm;

struct Node;

/// Map the model's free-text answer onto the closed intent set. The WIT `enum`
/// has no "other" case, so adversarial text cannot widen the set: anything we
/// don't recognise collapses to `Unknown`.
fn parse_intent(raw: &str) -> Intent {
    let s = raw.trim().to_ascii_lowercase();
    // Normalise separators so "billing-question" / "billing_question" /
    // "billing question" all match.
    let norm: String = s
        .chars()
        .map(|c| if c == '-' || c == ' ' { '_' } else { c })
        .collect();

    // Prefer an exact/contains match on the canonical labels.
    if norm.contains("billing_question") || norm.contains("billing") {
        Intent::BillingQuestion
    } else if norm.contains("technical_support")
        || norm.contains("technical")
        || norm.contains("tech_support")
    {
        Intent::TechnicalSupport
    } else if norm.contains("account_change")
        || norm.contains("account")
    {
        Intent::AccountChange
    } else if norm.contains("general_inquiry")
        || norm.contains("general")
        || norm.contains("inquiry")
    {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

/// Truncate to at most `max` bytes without splitting a UTF-8 char boundary.
fn truncate_bytes(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // `requires len(value.text) <= 4000` holds of every input; we defend
        // the model call regardless by bounding what we hand it.
        let text = truncate_bytes(message.text, 4000);

        // Single inference call: this node's entire authority.
        let system = "You classify a customer support message into exactly one \
                      intent. Reply with one of these labels and nothing else: \
                      billing_question, technical_support, account_change, \
                      general_inquiry, unknown.";
        let answer = inference_llm::infer(system, &text, "classify");

        let intent = parse_intent(&answer);

        // `ensures len(question) <= 512`: carry the (bounded) question forward,
        // clamped to 512 bytes. No entities are extracted by this node.
        let question = truncate_bytes(text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

If the platform team genuinely wants this node to make outbound HTTP calls, that should come through an actual update to the graph definition and `with` clause (and ideally a design review of sending untrusted text to an internal endpoint), not an out-of-band instruction — at which point I'd be glad to wire up `http-client` properly.

